    public static GradientDrawable round(Activity a,int fill,int stroke,int radius){GradientDrawable g=new GradientDrawable();g.setColor(fill);g.setCornerRadius(dp(a,radius));if(stroke!=Color.TRANSPARENT)g.setStroke(dp(a,1),stroke);return g;}
    public static GradientDrawable gradient(Activity a,int start,int end,int stroke,int radius){GradientDrawable g=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{start,end});g.setCornerRadius(dp(a,radius));if(stroke!=Color.TRANSPARENT)g.setStroke(dp(a,1),stroke);return g;}
    public static GradientDrawable velvet(Activity a,int radius){return gradient(a,Color.argb(240,31,37,52),Color.argb(224,14,18,27),BORDER_SOFT,radius);}public static GradientDrawable matte(Activity a,int radius){return round(a,SURFACE,HAIRLINE,radius);}public static View divider(Activity a){View v=new View(a);v.setBackgroundColor(BORDER_SOFT);return v;}
    public static<T extends View>T raised(Activity a,T v,int e){if(Build.VERSION.SDK_INT>=21){v.setElevation(dp(a,e));v.setTranslationZ(0f);}return v;}public static CortexGlyphView glyph(Activity a,String k,int c,boolean d){CortexGlyphView g=new CortexGlyphView(a,k,c,d);raised(a,g,2);return g;}
    public static View pressable(Activity a,View v,GradientDrawable base){if(Build.VERSION.SDK_INT>=21)v.setBackground(new RippleDrawable(ColorStateList.valueOf(Color.argb(30,185,236,255)),base,null));else v.setBackground(base);v.setClickable(true);v.setFocusable(true);raised(a,v,3);v.setOnTouchListener((x,e)->{if(Build.VERSION.SDK_INT>=21){if(e.getActionMasked()==MotionEvent.ACTION_DOWN){x.setTranslationZ(-dp(a,1));x.setScaleX(.982f);x.setScaleY(.982f);}else if(e.getActionMasked()==MotionEvent.ACTION_UP||e.getActionMasked()==MotionEvent.ACTION_CANCEL){x.animate().scaleX(1).scaleY(1).translationZ(0).setDuration(120).start();}}return false;});return v;}
    public static TextView text(Activity a,String s,int sp,int c){TextView v=new TextView(a);v.setTextSize(sp);v.setTextColor(c);v.setLineSpacing(0,1.10f);CortexTextUi.setReadable(v,s==null?"":s);return v;}public static TextView plain(Activity a,String s,int sp,int c){TextView v=new TextView(a);v.setTextSize(sp);v.setTextColor(c);CortexTextUi.setPlain(v,s==null?"":s);return v;}public static void medium(TextView v){v.setTypeface(Typeface.create("sans-serif-medium",Typeface.NORMAL));}public static void bold(TextView v){v.setTypeface(Typeface.create("sans-serif",Typeface.BOLD));}
    public static LinearLayout card(Activity a,int r){LinearLayout c=new LinearLayout(a);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(dp(a,17),dp(a,16),dp(a,17),dp(a,16));c.setBackground(velvet(a,r));raised(a,c,4);return c;}
    public static TextView chip(Activity a,String l,int c,boolean strong){TextView v=plain(a,l,strong?11:10,strong?TEXT:c);if(strong)medium(v);v.setGravity(Gravity.CENTER);v.setPadding(dp(a,12),0,dp(a,12),0);int fill=Color.argb(strong?34:16,Color.red(c),Color.green(c),Color.blue(c));int stroke=Color.argb(strong?100:54,Color.red(c),Color.green(c),Color.blue(c));v.setBackground(round(a,fill,stroke,999));return v;}
    public static TextView section(Activity a,String t){TextView h=plain(a,t,11,MUTED);medium(h);h.setPadding(0,dp(a,24),0,dp(a,10));return h;}public static TextView action(Activity a,String l,int c,boolean filled){TextView b=plain(a,l,12,filled?Color.rgb(7,13,20):c);medium(b);b.setGravity(Gravity.CENTER);b.setPadding(dp(a,14),0,dp(a,14),0);GradientDrawable base=filled?gradient(a,BRAND,Color.rgb(128,196,255),Color.TRANSPARENT,16):round(a,Color.argb(18,Color.red(c),Color.green(c),Color.blue(c)),Color.argb(74,Color.red(c),Color.green(c),Color.blue(c)),16);pressable(a,b,base);return b;}
    public static int semanticFor(String key){if(key==null)return BRAND;String k=key.toLowerCase();if(k.contains("urgent")||k.contains("error")||k.contains("alert"))return RED;if(k.contains("wait")||k.contains("remind")||k.contains("attention"))return ORANGE;if(k.contains("complete")||k.contains("resolved")||k.contains("healthy"))return GREEN;return BRAND;}

    /** Floating five-part dock: Now / Inbox / Capture / Library / Ask. */
    public static void addBottomNav(Activity a,LinearLayout root,String selected,Runnable ignored){String current=primeKey(selected);LinearLayout bar=new LinearLayout(a);bar.setGravity(Gravity.CENTER);bar.setPadding(dp(a,8),dp(a,6),dp(a,8),dp(a,6));bar.setBackground(gradient(a,Color.argb(246,20,25,36),Color.argb(240,11,15,23),Color.argb(74,165,205,255),25));addNav(a,bar,"today","Now","clock",current,CompactTodayActivity.class);addNav(a,bar,"inbox","Inbox","note",current,InboxActivity.class);addCapture(a,bar);addNav(a,bar,"library","Library","file",current,ProposalPeopleProjectsActivity.class);addNav(a,bar,"ask","Ask","brain",current,ProposalAskCortexActivity.class);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(a,74));p.setMargins(dp(a,14),dp(a,4),dp(a,14),dp(a,10));root.addView(bar,p);raised(a,bar,10);fitSystemBars(a,root);}
    private static void addCapture(Activity a,LinearLayout bar){LinearLayout wrap=new LinearLayout(a);wrap.setGravity(Gravity.CENTER);TextView v=plain(a,"+",30,Color.rgb(8,12,18));v.setGravity(Gravity.CENTER);v.setBackground(gradient(a,BRAND,Color.rgb(150,186,255),Color.argb(100,255,255,255),999));raised(a,v,12);v.setOnClickListener(x->{try{Intent i=new Intent(a,InboxActivity.class);i.putExtra("focus_composer",true);i.addFlags(Intent.FLAG_ACTIVITY_REORDER_TO_FRONT|Intent.FLAG_ACTIVITY_SINGLE_TOP);a.startActivity(i);}catch(Throwable ignored){}});wrap.addView(v,new LinearLayout.LayoutParams(dp(a,54),dp(a,54)));bar.addView(wrap,new LinearLayout.LayoutParams(dp(a,64),-1));}
    private static String primeKey(String s){if("home".equals(s)||"focus".equals(s)||"brief".equals(s)||"today".equals(s)||"now".equals(s))return"today";if("vault".equals(s)||"people".equals(s)||"memory".equals(s)||"world".equals(s)||"projects".equals(s)||"library".equals(s))return"library";if("ask".equals(s)||"brain".equals(s)||"cortex".equals(s))return"ask";if("input".equals(s)||"capture".equals(s)||"inbox".equals(s))return"inbox";return s==null?"":s;}
    private static void addNav(Activity a,LinearLayout bar,String key,String label,String glyph,String selected,Class<?> target){boolean on=key.equals(selected);LinearLayout item=new LinearLayout(a);item.setOrientation(LinearLayout.VERTICAL);item.setGravity(Gravity.CENTER);if(on)item.setBackground(round(a,Color.argb(32,Color.red(BRAND),Color.green(BRAND),Color.blue(BRAND)),Color.argb(74,Color.red(BRAND),Color.green(BRAND),Color.blue(BRAND)),18));CortexGlyphView g=CortexUi.glyph(a,glyph,on?BRAND:FAINT,false);item.addView(g,new LinearLayout.LayoutParams(dp(a,29),dp(a,29)));TextView t=plain(a,label,9,on?TEXT:MUTED);if(on)medium(t);t.setGravity(Gravity.CENTER);item.addView(t,new LinearLayout.LayoutParams(-1,dp(a,18)));if(!on)item.setOnClickListener(x->{try{Intent i=new Intent(a,target);i.addFlags(Intent.FLAG_ACTIVITY_REORDER_TO_FRONT|Intent.FLAG_ACTIVITY_SINGLE_TOP);a.startActivity(i);}catch(Throwable ignored){}});LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-1,1);p.setMargins(dp(a,2),0,dp(a,2),0);bar.addView(item,p);}
